// ../server/src/routes/terminal.ts
async function terminalRoutes(fastify, opts) {
  const { connectionManager } = opts;
  fastify.get("/ws/terminal/:serverId", { websocket: true }, (socket, req) => {
    const { serverId } = req.params;
    let shell = null;
    const buffer = new TerminalBuffer();
    const setup = async () => {
      try {
        shell = await connectionManager.getShell(serverId, {
          rows: 24,
          cols: 80,
          term: "xterm-256color"
        });
        shell.on("data", (data) => {
          if (socket.readyState === 1) {
            socket.send(data);
          }
          const hint = buffer.append(data);
          if (hint && socket.readyState === 1) {
            const snapshot = buffer.getLastCommandOutput();
            socket.send(
              JSON.stringify({
                type: "visualize-hint",
                hint,
                rawOutput: snapshot?.text ?? "",
                lineCount: snapshot?.lineCount ?? 0
              })
            );
          }
        });
        shell.on("close", () => {
          socket.close();
        });
        shell.stderr.on("data", (data) => {
          if (socket.readyState === 1) {
            socket.send(data);
          }
        });
        socket.on("message", (data) => {
          if (!shell) return;
          if (typeof data === "string" || data instanceof Buffer && data[0] === 1) {
            try {
              const str2 = typeof data === "string" ? data : data.toString();
              const msg = JSON.parse(str2);
              if (msg.type === "resize" && msg.rows && msg.cols) {
                shell.setWindow(msg.rows, msg.cols, 0, 0);
                return;
              }
              if (msg.type === "get-buffer") {
                const snapshot = buffer.getLastCommandOutput() ?? buffer.getSnapshot(msg.lastN ?? 100);
                if (socket.readyState === 1) {
                  socket.send(
                    JSON.stringify({
                      type: "buffer-snapshot",
                      text: snapshot.text,
                      lineCount: snapshot.lineCount
                    })
                  );
                }
                return;
              }
            } catch {
            }
          }
          shell.write(data);
        });
        socket.on("close", () => {
          if (shell) {
            shell.end();
            shell = null;
          }
          buffer.clear();
        });
        socket.on("error", () => {
          if (shell) {
            shell.end();
            shell = null;
          }
          buffer.clear();
        });
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to open terminal";
        socket.send(JSON.stringify({ type: "error", message }));
        socket.close();
      }
    };
    setup();
  });
}

// ../server/src/parsers/schemas/system.ts
init_zod();
var SystemInfoSchema = external_exports.object({
  hostname: external_exports.string(),
  uptime: external_exports.string(),
  os: external_exports.string(),
  kernel: external_exports.string(),
  architecture: external_exports.string()
});
var DiskUsageEntrySchema = external_exports.object({
  filesystem: external_exports.string(),
  size: external_exports.string(),
  used: external_exports.string(),
  available: external_exports.string(),
  usePercent: external_exports.number().min(0).max(100),
  mountPoint: external_exports.string()
});
var DiskUsageSchema = external_exports.array(DiskUsageEntrySchema);
var MemoryInfoSchema = external_exports.object({
  totalMb: external_exports.number().nonnegative(),
  usedMb: external_exports.number().nonnegative(),
  freeMb: external_exports.number().nonnegative(),
  availableMb: external_exports.number().nonnegative(),
  swapTotalMb: external_exports.number().nonnegative(),
  swapUsedMb: external_exports.number().nonnegative()
});
var NetworkInterfaceSchema = external_exports.object({
  name: external_exports.string(),
  status: external_exports.enum(["UP", "DOWN", "UNKNOWN"]),
  ipAddresses: external_exports.array(external_exports.string())
});
var NetworkInterfacesSchema = external_exports.array(NetworkInterfaceSchema);
var SystemDashboardSchema = external_exports.object({
  system: SystemInfoSchema,
  disks: DiskUsageSchema,
  memory: MemoryInfoSchema,
  network: NetworkInterfacesSchema
});

// ../server/src/routes/system.ts
async function systemRoutes(fastify, opts) {
  const { orchestrator, connectionManager } = opts;
  function requireConnected(serverId) {
    const state = connectionManager.getState(serverId);
    if (state.status !== "connected") {
      throw Object.assign(new Error(`Server "${serverId}" is not connected`), {
        statusCode: 400
      });
    }
  }
  fastify.get(
    "/api/servers/:id/system",
    async (req, reply) => {
      const { id } = req.params;
      requireConnected(id);
      const plan = {
        steps: [
          {
            id: "system-info",
            command: "uname -a && uptime -p && cat /etc/os-release",
            schema: SystemInfoSchema,
            fallbackCommands: ["uname -a && uptime && cat /etc/os-release"],
            timeout: 1e4
          },
          {
            id: "disk",
            command: "df -h",
            schema: DiskUsageSchema,
            timeout: 1e4
          },
          {
            id: "memory",
            command: "free -m",
            schema: MemoryInfoSchema,
            timeout: 1e4
          },
          {
            id: "network",
            command: "ip -brief addr",
            schema: NetworkInterfacesSchema,
            fallbackCommands: ["ip addr show", "ifconfig"],
            timeout: 1e4
          }
        ],
        parallel: true
      };
      try {
        const result = await orchestrator.execute(
          id,
          plan,
          (results) => {
            const system = results.get("system-info") ?? {
              hostname: "unknown",
              uptime: "unknown",
              os: "unknown",
              kernel: "unknown",
              architecture: "unknown"
            };
            const disks = results.get("disk") ?? [];
            const memory = results.get("memory") ?? {
              totalMb: 0,
              usedMb: 0,
              freeMb: 0,
              availableMb: 0,
              swapTotalMb: 0,
              swapUsedMb: 0
            };
            const network = results.get("network") ?? [];
            return SystemDashboardSchema.parse({
              system,
              disks,
              memory,
              network
            });
          }
        );
        return {
          success: true,
          data: result.data,
          steps: result.steps.map((s) => ({
            stepId: s.stepId,
            parsedBy: s.parsedBy,
            latencyMs: s.latencyMs,
            success: s.success
          })),
          totalLatencyMs: result.totalLatencyMs
        };
      } catch (err) {
        reply.code(500);
        return {
          success: false,
          error: err instanceof Error ? err.message : "Failed to fetch system data"
        };
      }
    }
  );
  fastify.get(
    "/api/servers/:id/system/disk",
    async (req, reply) => {
      const { id } = req.params;
      requireConnected(id);
      const plan = {
        steps: [
          {
            id: "disk",
            command: "df -h",
            schema: DiskUsageSchema,
            timeout: 1e4
          }
        ]
      };
      try {
        const result = await orchestrator.execute(
          id,
          plan,
          (results) => results.get("disk")
        );
        return {
          success: true,
          data: result.data,
          parsedBy: result.steps[0]?.parsedBy,
          latencyMs: result.totalLatencyMs
        };
      } catch (err) {
        reply.code(500);
        return {
          success: false,
          error: err instanceof Error ? err.message : "Failed to fetch disk data"
        };
      }
    }
  );
  fastify.get(
    "/api/servers/:id/system/memory",
    async (req, reply) => {
      const { id } = req.params;
      requireConnected(id);
      const plan = {
        steps: [
          {
            id: "memory",
            command: "free -m",
            schema: MemoryInfoSchema,
            timeout: 1e4
          }
        ]
      };
      try {
        const result = await orchestrator.execute(
          id,
          plan,
          (results) => results.get("memory")
        );
        return {
          success: true,
          data: result.data,
          parsedBy: result.steps[0]?.parsedBy,
          latencyMs: result.totalLatencyMs
        };
      } catch (err) {
        reply.code(500);
        return {
          success: false,
          error: err instanceof Error ? err.message : "Failed to fetch memory data"
        };
      }
    }
  );
}

