// ../server/src/routes/stats.ts
async function statsRoutes(fastify, opts) {
  const { usageTracker, outputCache } = opts;
  fastify.get("/api/stats/llm", async () => {
    const cacheStats = outputCache.getStats();
    const summary = usageTracker.getSummary(cacheStats);
    return { success: true, data: summary };
  });
  fastify.post("/api/stats/llm/reset", async () => {
    usageTracker.reset();
    outputCache.reset();
    return { success: true };
  });
}

// ../server/src/routes/llm.ts
async function llmRoutes(app, opts) {
  const { pipeline } = opts;
  app.get("/api/llm/config", async () => {
    const provider = pipeline.llmProvider;
    const config = {
      provider: provider ? provider.name : "none",
      model: provider?.model ?? "gpt-4.1-mini",
      hasApiKey: !!provider
    };
    return { success: true, data: config };
  });
  app.put(
    "/api/llm/config",
    async (req) => {
      const { provider, apiKey, model } = req.body;
      if (provider === "none") {
        pipeline.setLLMProvider(void 0);
        return { success: true, data: { provider: "none", model: "", hasApiKey: false } };
      }
      if (provider === "openai") {
        if (!apiKey) {
          return { success: false, error: "API key is required for OpenAI provider" };
        }
        const { OpenAIProvider: OpenAIProvider2 } = await Promise.resolve().then(() => (init_openai2(), openai_exports));
        const llmProvider = new OpenAIProvider2(apiKey, model ?? "gpt-4.1-mini");
        pipeline.setLLMProvider(llmProvider);
        console.log(`\u{1F916} LLM provider updated: OpenAI (${model ?? "gpt-4.1-mini"})`);
        return {
          success: true,
          data: {
            provider: "openai",
            model: model ?? "gpt-4.1-mini",
            hasApiKey: true
          }
        };
      }
      return { success: false, error: `Unknown provider: ${provider}` };
    }
  );
  app.get("/api/llm/models", async () => {
    return {
      success: true,
      data: {
        openai: [
          { id: "gpt-4.1-nano", name: "GPT-4.1 Nano", description: "Fastest, lowest cost \u2014 classification & summaries" },
          { id: "gpt-4.1-mini", name: "GPT-4.1 Mini", description: "Fast, affordable \u2014 best for parsing", recommended: true },
          { id: "gpt-4.1", name: "GPT-4.1", description: "Structured output, schema generation" },
          { id: "gpt-4o", name: "GPT-4o", description: "Capable general-purpose model" },
          { id: "gpt-4o-mini", name: "GPT-4o Mini", description: "Legacy mini model" },
          { id: "o4-mini", name: "o4-mini", description: "Reasoning model" },
          { id: "gpt-5.4", name: "GPT-5.4", description: "Most capable, highest cost \u2014 planning & reflection" }
        ]
      }
    };
  });
}

// ../server/src/routes/fleet.ts
async function fleetRoutes(fastify, opts) {
  const { orchestrator, connectionManager, configStore } = opts;
  fastify.get("/api/fleet/overview", async (_req, reply) => {
    const allServers = await configStore.getServers();
    const summaries = [];
    const promises = allServers.map(async (srv) => {
      const state = connectionManager.getState(srv.id);
      const status = state.status;
      const base = {
        id: srv.id,
        name: srv.name,
        host: srv.host,
        port: srv.port ?? 22,
        status,
        tags: srv.tags ?? []
      };
      if (status !== "connected") {
        return base;
      }
      const plan = {
        steps: [
          {
            id: "system-info",
            command: "uname -a && uptime -p && cat /etc/os-release",
            schema: SystemInfoSchema,
            fallbackCommands: ["uname -a && uptime && cat /etc/os-release"],
            timeout: 8e3
          },
          {
            id: "memory",
            command: "free -m",
            schema: MemoryInfoSchema,
            timeout: 8e3
          },
          {
            id: "disk",
            command: "df -h",
            schema: DiskUsageSchema,
            timeout: 8e3
          }
        ],
        parallel: true
      };
      try {
        const result = await orchestrator.execute(
          srv.id,
          plan,
          (results2) => {
            const sysInfo2 = results2.get("system-info");
            const memory2 = results2.get("memory");
            const diskArr2 = results2.get("disk");
            return { sysInfo: sysInfo2, memory: memory2, diskArr: diskArr2 };
          }
        );
        const { sysInfo, memory, diskArr } = result.data;
        let totalDiskGb2 = 0;
        let usedDiskGb2 = 0;
        if (Array.isArray(diskArr)) {
          for (const fs2 of diskArr) {
            if (fs2.mountPoint === "/" || fs2.mountPoint.startsWith("/home") || fs2.mountPoint.startsWith("/data")) {
              totalDiskGb2 += parseFloat(String(fs2.size ?? "0")) || 0;
              usedDiskGb2 += parseFloat(String(fs2.used ?? "0")) || 0;
            }
          }
        }
        return {
          ...base,
          system: sysInfo ? {
            hostname: sysInfo.hostname,
            os: sysInfo.os,
            uptime: sysInfo.uptime,
            kernel: sysInfo.kernel,
            architecture: sysInfo.architecture
          } : void 0,
          memory: memory ? {
            totalMb: memory.totalMb,
            usedMb: memory.usedMb,
            usedPercent: memory.totalMb > 0 ? Math.round(memory.usedMb / memory.totalMb * 100) : 0
          } : void 0,
          disk: totalDiskGb2 > 0 ? {
            totalGb: Math.round(totalDiskGb2 * 10) / 10,
            usedGb: Math.round(usedDiskGb2 * 10) / 10,
            usedPercent: Math.round(usedDiskGb2 / totalDiskGb2 * 100)
          } : void 0,
          latencyMs: result.totalLatencyMs
        };
      } catch (err) {
        return {
          ...base,
          error: err instanceof Error ? err.message : "Failed to fetch data"
        };
      }
    });
    const results = await Promise.allSettled(promises);
    for (const r of results) {
      if (r.status === "fulfilled") {
        summaries.push(r.value);
      }
    }
    const connected = summaries.filter((s) => s.status === "connected").length;
    let totalMemoryMb = 0;
    let usedMemoryMb = 0;
    let totalDiskGb = 0;
    let usedDiskGb = 0;
    for (const s of summaries) {
      if (s.memory) {
        totalMemoryMb += s.memory.totalMb;
        usedMemoryMb += s.memory.usedMb;
      }
      if (s.disk) {
        totalDiskGb += s.disk.totalGb;
        usedDiskGb += s.disk.usedGb;
      }
    }
    const overview = {
      servers: summaries,
      totals: {
        total: summaries.length,
        connected,
        disconnected: summaries.length - connected,
        totalMemoryMb,
        usedMemoryMb,
        totalDiskGb,
        usedDiskGb
      },
      fetchedAt: (/* @__PURE__ */ new Date()).toISOString()
    };
    return { success: true, data: overview };
  });
  fastify.put(
    "/api/servers/:id/tags",
    async (req, reply) => {
      const { id } = req.params;
      const { tags } = req.body ?? {};
      if (!Array.isArray(tags) || tags.some((t) => typeof t !== "string")) {
        reply.code(400);
        return { success: false, error: "tags must be an array of strings" };
      }
      const server = await configStore.getServer(id);
      if (!server) {
        reply.code(404);
        return { success: false, error: "Server not found" };
      }
      const updated = await configStore.updateServer(id, { tags });
      return { success: true, data: updated };
    }
  );
}

// ../server/src/routes/sessions.ts
async function sessionRoutes(fastify, opts) {
  const { sessionStore, connectionManager } = opts;
  fastify.get("/api/sessions", async () => {
    return sessionStore.listSessions();
  });
  fastify.get(
    "/api/sessions/:serverId",
    async (req, reply) => {
      const state = await sessionStore.getSession(req.params.serverId);
      if (!state) {
        reply.code(404);
        return { error: "Session not found" };
      }
      return state;
    }
  );
  fastify.put("/api/sessions/:serverId", async (req, reply) => {
    const parsed = SessionStateSchema.safeParse(req.body);
    if (!parsed.success) {
      reply.code(400);
      return { error: "Invalid session state", details: parsed.error.flatten() };
    }
    if (parsed.data.serverId !== req.params.serverId) {
      reply.code(400);
      return { error: "serverId in body does not match path" };
    }
    await sessionStore.saveSession(parsed.data);
    reply.code(204);
  });
  fastify.delete(
    "/api/sessions/:serverId",
    async (req, reply) => {
      await sessionStore.deleteSession(req.params.serverId);
      reply.code(204);
    }
  );
  fastify.post(
    "/api/sessions/:serverId/hibernate",
    async (req, reply) => {
      const { serverId } = req.params;
      await sessionStore.markHibernated(serverId);
      try {
        await connectionManager.disconnect(serverId);
      } catch {
      }
      reply.code(204);
    }
  );
}

// ../server/src/routes/agent.ts
async function agentRoutes(fastify, opts) {
  const { connectionManager, agent } = opts;
  function requireConnected(serverId) {
    const state = connectionManager.getState(serverId);
    if (state.status !== "connected") {
      throw Object.assign(new Error(`Server "${serverId}" is not connected`), {
        statusCode: 400
      });
    }
  }
  fastify.post(
    "/api/servers/:id/agent/investigate",
    async (req, reply) => {
      const { id } = req.params;
      requireConnected(id);
      const { question, maxSteps, readOnly } = req.body ?? {};
      if (!question || typeof question !== "string" || question.trim().length === 0) {
        reply.code(400);
        return { success: false, error: "question is required" };
      }
      if (question.length > 2e3) {
        reply.code(400);
        return { success: false, error: "question must be under 2000 characters" };
      }
      try {
        const result = await agent.investigate(id, question.trim(), {
          maxSteps: Math.min(maxSteps ?? 10, 15),
          readOnly: readOnly ?? true
        });
        return { success: true, data: result };
      } catch (err) {
        reply.code(500);
        return {
          success: false,
          error: err instanceof Error ? err.message : "Agent investigation failed"
        };
      }
    }
  );
  fastify.post(
    "/api/servers/:id/agent/:sessionId/abort",
    async (req) => {
      const { sessionId } = req.params;
      agent.abort(sessionId);
      return { success: true };
    }
  );
  fastify.get(
    "/ws/agent/:id/:sessionId",
    { websocket: true },
    (socket, req) => {
      const { sessionId } = req.params;
      const handler = (data) => {
        try {
          socket.send(JSON.stringify(data));
        } catch {
        }
      };
      agent.events.on(`step:${sessionId}`, handler);
      socket.on("message", (msg) => {
        const text = msg.toString();
        if (text === "abort") {
          agent.abort(sessionId);
        }
      });
      socket.on("close", () => {
        agent.events.off(`step:${sessionId}`, handler);
      });
    }
  );
}

