// ../server/src/agent/tools/sftp-read.ts
init_zod();
var SftpReadParams = external_exports.object({
  path: external_exports.string().describe("Absolute path to the file to read"),
  maxBytes: external_exports.number().int().min(1).max(1048576).optional().describe("Maximum bytes to read (default: 65536, max: 1MB)")
});
var sftpReadTool = {
  name: "sftp_read",
  description: "Read a file from the server via SFTP. Returns the file content as text. Use this to inspect configuration files, logs, or scripts.",
  parameters: SftpReadParams,
  securityTier: "read",
  async execute(rawArgs, context) {
    try {
      const args = SftpReadParams.parse(rawArgs);
      const { path: path2, maxBytes = 65536 } = args;
      if (!path2.startsWith("/")) {
        return {
          success: false,
          output: "",
          error: "Path must be absolute (start with /)"
        };
      }
      if (path2.includes("..")) {
        return {
          success: false,
          output: "",
          error: "Path traversal (..) is not allowed"
        };
      }
      const sftp = await context.ssh.getSftp(context.serverId);
      const content = await new Promise((resolve2, reject) => {
        const chunks = [];
        let totalBytes = 0;
        const stream = sftp.createReadStream(path2, {
          start: 0,
          end: maxBytes - 1
        });
        stream.on("data", (chunk) => {
          totalBytes += chunk.length;
          if (totalBytes <= maxBytes) {
            chunks.push(chunk);
          }
        });
        stream.on("end", () => {
          resolve2(Buffer.concat(chunks).toString("utf-8"));
        });
        stream.on("error", (err) => {
          reject(err);
        });
      });
      const truncated = content.length >= maxBytes;
      return {
        success: true,
        output: content,
        metadata: {
          path: path2,
          bytes: content.length,
          truncated
        }
      };
    } catch (err) {
      return {
        success: false,
        output: "",
        error: `sftp_read failed: ${err.message}`
      };
    }
  }
};

