var MODEL_PRICING = {
  "gpt-4.1": { input: 2e-3, output: 8e-3 },
  "gpt-4.1-mini": { input: 4e-4, output: 16e-4 },
  "gpt-4.1-nano": { input: 1e-4, output: 4e-4 },
  "gpt-4o": { input: 25e-4, output: 0.01 },
  "gpt-4o-mini": { input: 15e-5, output: 6e-4 },
  "gpt-5.4": { input: 0.01, output: 0.04 },
  "o4-mini": { input: 11e-4, output: 44e-4 },
  "gpt-4-turbo": { input: 0.01, output: 0.03 },
  "gpt-4": { input: 0.03, output: 0.06 },
  "gpt-3.5-turbo": { input: 5e-4, output: 15e-4 },
  "claude-3-opus": { input: 0.015, output: 0.075 },
  "claude-3-sonnet": { input: 3e-3, output: 0.015 },
  "claude-3-haiku": { input: 25e-5, output: 125e-5 },
  "claude-3.5-sonnet": { input: 3e-3, output: 0.015 },
  "claude-4-sonnet": { input: 3e-3, output: 0.015 }
};
var DEFAULT_PRICING = { input: 5e-3, output: 0.015 };
var LLMUsageTracker = class {
  entries = [];
  totalInputTokens = 0;
  totalOutputTokens = 0;
  totalLatencyMs = 0;
  totalCostUsd = 0;
  callsByModel = /* @__PURE__ */ new Map();
  callsByCommand = /* @__PURE__ */ new Map();
  /**
   * Record a completed LLM call.
   */
  recordCall(entry) {
    this.entries.push(entry);
    this.totalInputTokens += entry.inputTokens;
    this.totalOutputTokens += entry.outputTokens;
    this.totalLatencyMs += entry.latencyMs;
    const pricing = this.getPricing(entry.model);
    this.totalCostUsd += entry.inputTokens / 1e3 * pricing.input + entry.outputTokens / 1e3 * pricing.output;
    const modelCount = this.callsByModel.get(entry.model) ?? 0;
    this.callsByModel.set(entry.model, modelCount + 1);
    const cmdCount = this.callsByCommand.get(entry.command) ?? 0;
    this.callsByCommand.set(entry.command, cmdCount + 1);
  }
  /**
   * Get aggregate usage summary.
   */
  getSummary(cacheStats) {
    const totalCalls = this.entries.length;
    return {
      totalCalls,
      totalInputTokens: this.totalInputTokens,
      totalOutputTokens: this.totalOutputTokens,
      estimatedCostUsd: Math.round(this.totalCostUsd * 1e6) / 1e6,
      // 6 decimal places
      averageLatencyMs: totalCalls > 0 ? Math.round(this.totalLatencyMs / totalCalls) : 0,
      callsByModel: Object.fromEntries(this.callsByModel),
      callsByCommand: Object.fromEntries(this.callsByCommand),
      ...cacheStats ? { cache: cacheStats } : {}
    };
  }
  /**
   * Reset all tracked data.
   */
  reset() {
    this.entries = [];
    this.totalInputTokens = 0;
    this.totalOutputTokens = 0;
    this.totalLatencyMs = 0;
    this.totalCostUsd = 0;
    this.callsByModel.clear();
    this.callsByCommand.clear();
  }
  /**
   * Get the number of recorded calls.
   */
  get totalCallCount() {
    return this.entries.length;
  }
  // ── Internal ──
  getPricing(model) {
    if (MODEL_PRICING[model]) return MODEL_PRICING[model];
    for (const [key, pricing] of Object.entries(MODEL_PRICING)) {
      if (model.startsWith(key)) return pricing;
    }
    return DEFAULT_PRICING;
  }
};

